// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Load font at module level to guarantee availability before frame 0
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type EyeIconProps = Record<string, any>;

const EyeIcon: React.FC<EyeIconProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 8,
  eyeColor = "#00e5ff",
  pupilColor = "#0a0a0a",
  scleraColor = "#ffffff",
  strokeColor = "#ffffff",
  strokeWidth = 2.0,
  sizeMultiplier = 1.0,
  lookAround = true,
  showLabel = true,
  label = "VISION",
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Logic to prevent parser errors for background color
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Total duration in frames for percentage-based interpolations
  const durationFrames = durationInSeconds * fps;

  // 1. Eyelid Opening Animation (0 = closed flat line, 1 = fully open almond)
  // Sequence: Closed -> Open -> Blink Down -> Blink Up -> Close at end
  const openFractions = [0, 0.05, 0.1, 0.4, 0.42, 0.44, 0.9, 0.95, 1];
  const openValues = [0, 0, 1, 1, 0, 1, 1, 0, 0];
  const openAmount = interpolate(
    frame,
    openFractions.map((p) => p * durationFrames),
    openValues,
    {
      easing: Easing.inOut(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // 2. Iris Look X Animation (Left to Right movement)
  // Sequence: Center -> Right -> Left -> Center
  const lookXFractions = [0, 0.45, 0.5, 0.55, 0.6, 0.65, 0.7, 1];
  const lookXValues = [0, 0, 16, 16, -16, -16, 0, 0];
  const currentLookX = lookAround
    ? interpolate(
        frame,
        lookXFractions.map((p) => p * durationFrames),
        lookXValues,
        {
          easing: Easing.inOut(Easing.ease),
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        }
      )
    : 0;

  // 3. Iris Look Y Animation (Slight up/down movement)
  // Sequence: Center -> Look Up slightly -> Center
  const lookYFractions = [0, 0.2, 0.25, 0.35, 0.4, 1];
  const lookYValues = [0, 0, -8, -8, 0, 0];
  const currentLookY = lookAround
    ? interpolate(
        frame,
        lookYFractions.map((p) => p * durationFrames),
        lookYValues,
        {
          easing: Easing.inOut(Easing.ease),
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        }
      )
    : 0;

  // 4. Pupil Dilation Animation
  // Sequence: Normal -> Dilate -> Normal
  const dilateFractions = [0, 0.75, 0.8, 0.85, 0.9, 1];
  const dilateValues = [0, 0, 1, 1, 0, 0];
  const currentDilation = interpolate(
    frame,
    dilateFractions.map((p) => p * durationFrames),
    dilateValues,
    {
      easing: Easing.inOut(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Calculate dynamic paths for the eye based on `openAmount`
  // Midpoint is 50. When closed, top and bottom curves rest at 50.
  // When open, top goes up to 5, bottom goes down to 95 for a wide almond shape.
  const topCurveY = interpolate(openAmount, [0, 1], [50, 5]);
  const bottomCurveY = interpolate(openAmount, [0, 1], [50, 95]);

  // Construct the responsive SVG path
  const scleraPath = `M 5 50 Q 50 ${topCurveY} 95 50 Q 50 ${bottomCurveY} 5 50 Z`;

  // Base sizing logic
  const svgSize = width * 0.6 * sizeMultiplier;
  const irisSize = 20;
  const basePupilSize = 8;
  const maxDilationIncrease = 6;
  
  const animatedPupilRadius = basePupilSize + currentDilation * maxDilationIncrease;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: spaceGroteskFamily,
        justifyContent: "center",
        alignItems: "center",
        flexDirection: "column",
        transition: "none",
      }}
    >
      <div
        style={{
          width: svgSize,
          height: svgSize,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        <svg
          viewBox="0 0 100 100"
          style={{ width: "100%", height: "100%", overflow: "visible", transition: "none" }}
        >
          <defs>
            <clipPath id="scleraClip">
              <path d={scleraPath} />
            </clipPath>
          </defs>

          {/* Sclera Background */}
          <path
            d={scleraPath}
            fill={scleraColor}
            style={{ transition: "none" }}
          />

          {/* Iris and Pupil Group (Clipped by Sclera shape) */}
          <g clipPath="url(#scleraClip)" style={{ transition: "none" }}>
            {/* Iris */}
            <circle
              cx={50 + currentLookX}
              cy={50 + currentLookY}
              r={irisSize}
              fill={eyeColor}
              style={{ transition: "none" }}
            />
            
            {/* Pupil */}
            <circle
              cx={50 + currentLookX}
              cy={50 + currentLookY}
              r={animatedPupilRadius}
              fill={pupilColor}
              style={{ transition: "none" }}
            />

            {/* Iris Highlight */}
            <circle
              cx={50 + currentLookX - irisSize * 0.3}
              cy={50 + currentLookY - irisSize * 0.3}
              r={irisSize * 0.2}
              fill="#ffffff"
              opacity={0.8}
              style={{ transition: "none" }}
            />
          </g>

          {/* Sclera Outline (Drawn on top to ensure clean border) */}
          <path
            d={scleraPath}
            fill="none"
            stroke={strokeColor}
            strokeWidth={strokeWidth}
            strokeLinejoin="round"
            style={{ transition: "none" }}
          />
        </svg>
      </div>

      {/* Optional Label */}
      {showLabel && (
        <div
          style={{
            marginTop: width * 0.05 * sizeMultiplier,
            fontSize: width * 0.04 * sizeMultiplier,
            color: strokeColor,
            fontWeight: "bold",
            letterSpacing: "0.2em",
            opacity: openAmount, // Fade in/out with the eye
            transition: "none",
          }}
        >
          {label}
        </div>
      )}
    </AbsoluteFill>
  );
};

export default EyeIcon;